class Solution { public: int swimInWater(vector<vector<int>>& grid){int n=grid.size();vector<vector<int>> distance(n,vector<int>(n,INT_MAX));priority_queue<array<int,3>,vector<array<int,3>>,greater<array<int,3>>> heap;distance[0][0]=grid[0][0];heap.push({grid[0][0],0,0});int directions[5]={-1,0,1,0,-1};while(!heap.empty()){auto [time,row,column]=heap.top();heap.pop();if(time!=distance[row][column])continue;if(row==n-1&&column==n-1)return time;for(int d=0;d<4;++d){int nextRow=row+directions[d],nextColumn=column+directions[d+1];if(nextRow<0||nextRow>=n||nextColumn<0||nextColumn>=n)continue;int next=max(time,grid[nextRow][nextColumn]);if(next<distance[nextRow][nextColumn]){distance[nextRow][nextColumn]=next;heap.push({next,nextRow,nextColumn});}}}return -1;} };
